/**
 * Predicted money route — output of the platform's own risk model.
 *
 * The panel is deliberately blunt about provenance: every number here is
 * computed by TRACIFY from observed chain data, the route shown is one the graph
 * actually contains, and the drivers are the model's own signed contributions.
 * Nothing on this panel is generated by a language model.
 */
import { ArrowRight, Cpu, Gauge, ShieldAlert } from "lucide-react";

import { Chip, Mono } from "@/components/vt/badges";
import { ClayCard } from "@/components/vt/clay";
import { truncateAddress } from "@/lib/domain";
import type {
  MlBand,
  RouteCandidatePrediction,
  RoutePredictionResult,
} from "@/lib/api/backend-types";

const BAND_TONE: Record<MlBand, "positive" | "neutral" | "info" | "warning" | "critical"> = {
  low: "positive",
  moderate: "neutral",
  elevated: "info",
  high: "warning",
  severe: "critical",
};

const PRIORITY_COPY: Record<string, string> = {
  urgent: "Serve a freeze / information request now",
  priority: "Queue for analyst review",
  routine: "Monitor — no regulated counterparty yet",
};

function RouteTrail({ addresses }: { addresses: string[] }) {
  return (
    <div className="flex flex-wrap items-center gap-1.5">
      {addresses.map((address, i) => (
        <span key={`${address}-${i}`} className="flex items-center gap-1.5">
          <Mono className="rounded-md bg-muted/60 px-1.5 py-0.5">
            {truncateAddress(address, 6, 4)}
          </Mono>
          {i < addresses.length - 1 && (
            <ArrowRight className="size-3 text-muted-foreground" aria-hidden />
          )}
        </span>
      ))}
    </div>
  );
}

function DriverBar({ contribution, note }: { contribution: number; note: string }) {
  const magnitude = Math.min(100, Math.abs(contribution) * 4);
  return (
    <div className="space-y-1">
      <div className="flex items-baseline justify-between gap-3 text-xs">
        <span className="text-foreground/85">{note}</span>
        <Mono className="text-muted-foreground">
          {contribution > 0 ? "+" : ""}
          {contribution} pts
        </Mono>
      </div>
      <div className="h-1.5 overflow-hidden rounded-full bg-muted/60">
        <div
          className={contribution >= 0 ? "h-full bg-primary/70" : "h-full bg-muted-foreground/50"}
          style={{ width: `${magnitude}%` }}
        />
      </div>
    </div>
  );
}

function CandidateRow({ route, rank }: { route: RouteCandidatePrediction; rank: number }) {
  return (
    <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border/60 px-3 py-2.5">
      <div className="space-y-1.5">
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <span>Candidate {rank}</span>
          <Chip tone={BAND_TONE[route.band]}>{route.band}</Chip>
        </div>
        <RouteTrail addresses={route.addresses} />
      </div>
      <div className="text-right">
        <Mono className="text-base font-semibold">{route.routeScore}</Mono>
        <p className="text-[11px] text-muted-foreground">route score</p>
      </div>
    </div>
  );
}

export function RoutePredictionPanel({ result }: { result: RoutePredictionResult }) {
  const predicted = result.predicted;

  if (!predicted) {
    return (
      <ClayCard className="p-5">
        <p className="text-sm text-muted-foreground">
          No candidate route could be enumerated from the stored graph. Re-run the trace with a
          greater hop budget or a lower value floor.
        </p>
      </ClayCard>
    );
  }

  return (
    <div className="space-y-4">
      <ClayCard className="space-y-4 p-5">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div className="space-y-1">
            <p className="text-[11px] uppercase tracking-[0.14em] text-muted-foreground">
              Predicted money route
            </p>
            <h3 className="text-lg font-semibold">
              {Math.max(0, predicted.addresses.length - 1)} hops ·{" "}
              {Math.round((predicted.features['valueRetention'] ?? 0) * 100)}% of value retained
            </h3>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <Chip tone={BAND_TONE[predicted.band]} dot>
              {predicted.band} · {predicted.routeScore}/100
            </Chip>
            <Chip tone="intel">
              <Gauge className="mr-1 size-3" />
              {Math.round(predicted.confidence * 100)}% confidence
            </Chip>
          </div>
        </div>

        <RouteTrail addresses={predicted.addresses} />

        <p className="text-sm leading-relaxed text-muted-foreground">{predicted.rationale}</p>

        <div className="flex flex-wrap items-center gap-2 border-t border-border/60 pt-3">
          <Chip tone={predicted.priority === "urgent" ? "critical" : "neutral"}>
            <ShieldAlert className="mr-1 size-3" />
            {PRIORITY_COPY[predicted.priority] ?? predicted.priority}
          </Chip>
          <Chip tone="neutral">
            <Cpu className="mr-1 size-3" />
            {result.modelId} · {result.modelVersion}
          </Chip>
          <Chip tone="neutral">features v{result.featureSchemaVersion}</Chip>
          <Chip tone={result.source === "remote" ? "info" : "neutral"}>
            {result.source === "remote" ? "trained model" : "explainable baseline"}
          </Chip>
          {result.degraded && (
            <Chip tone="warning">degraded: {result.degradedReason ?? "remote model unavailable"}</Chip>
          )}
        </div>
      </ClayCard>

      <ClayCard className="space-y-3 p-5">
        <div>
          <p className="text-[11px] uppercase tracking-[0.14em] text-muted-foreground">
            Why the model ranked this route first
          </p>
          <p className="mt-1 text-xs text-muted-foreground">
            Signed contributions to the {predicted.routeScore}-point score. Every feature is measured
            from observed transfers — none of it is inferred by a language model.
          </p>
        </div>
        <div className="space-y-2.5">
          {predicted.contributions.slice(0, 8).map((driver) => (
            <DriverBar
              key={driver.feature}
              contribution={driver.contribution}
              note={driver.note}
            />
          ))}
        </div>
      </ClayCard>

      {result.ranked.length > 1 && (
        <ClayCard className="space-y-3 p-5">
          <p className="text-[11px] uppercase tracking-[0.14em] text-muted-foreground">
            Rejected candidates ({result.ranked.length - 1})
          </p>
          <div className="space-y-2">
            {result.ranked.slice(1, 6).map((route, i) => (
              <CandidateRow key={route.routeId} route={route} rank={i + 2} />
            ))}
          </div>
        </ClayCard>
      )}
    </div>
  );
}
